struct Stop{at:u32,token:r::CancelToken}
impl r::ScanObserver for Stop{fn on_entry(&self,p:&r::ScanProgress){if p.recorded_entries==self.at{self.token.cancel();}}}
fn main(){let index:Value=serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_NATIVE_WALK_INDEX").unwrap()).unwrap()).unwrap();let initial=index["root"].as_str().unwrap();let mut cases=Vec::new();for (case,action,depth,budget,pre,stop) in [("selection-cancelled","cancel",8,128,false,0),("complete","select",8,128,false,0),("depth-partial","select",1,128,false,0),("pre-cancelled","select",8,128,true,0),("observer-cancelled","select",8,128,false,4),("budget-partial","select",8,3,false,0),("depth-zero","select",0,128,false,0),("root-budget","select",8,1,false,0)]{let mut reg=Registry::new(4).unwrap();let scope_id=id("native-probe-scope");let session_id=id(&format!("native-{case}"));let picker=s::PickerOptions::new(initial).unwrap();eprintln!("WATER_PICKER_CASE {action}");let selected=s::select_scope(&mut reg,&scope_id,&picker).unwrap();let options=r::ScanOptions::new(depth,budget,32).unwrap();let policy=json!({"platform":"windows","traversal":"handle_relative_no_follow","ordinary_content_read":false,"native_user_gesture_authenticated":false,"race_protection_verified":false,"coverage_basis":"declared_policy","limits":{"max_depth":depth,"max_entries":budget,"max_dir_entries":32}});let mut snapshots=Vec::new();let mut source_report=Value::Null;let selection=if let Some(selected)=selected{let cancel=r::CancelToken::new();if pre{cancel.cancel();}let scan=if stop>0{r::scan_registered_with_observer(&mut reg,selected.scope(),selected.root_path(),&session_id,&options,&cancel,&Stop{at:stop,token:cancel.clone()}).unwrap()}else{r::scan_registered(&mut reg,selected.scope(),selected.root_path(),&session_id,&options,&cancel).unwrap()};let report=scan.report();water_contracts::v1::validate_report(report).unwrap();source_report=serde_json::to_value(report).unwrap();let view=water_report_view::v1::project_report(report).unwrap();let summary=water_summary_export::v1::summarize_report(report).unwrap();let q=water_redacted_report::v1::to_json(&water_redacted_report::v1::redact_report(report).unwrap()).unwrap();assert_eq!(q,r::redacted_json(&scan).unwrap());snapshots.push(json!({"source_kind":"native_scope_metadata","view":view,"summary":summary,"redacted_json":q}));reg.revoke(selected.scope()).unwrap();"confirmed"}else{"cancelled"};assert!(reg.is_empty());cases.push(json!({"id":case,"source_report":source_report,"bundle":{"bundle_version":"water.native-session-bundle.v1","session_id":session_id,"read_only":true,"selection":selection,"confirmation_source":"native_directory_dialog","policy":policy,"snapshots":snapshots}}));}println!("{}",json!({"fixture_version":"water.native-session.cases.v1","actual_S_P_R_A_E_H_Q":true,"new_V_implementation_used":false,"new_W_implementation_used":false,"cases":cases}));}
